values
  ('e959806d-fea5-470d-ae2b-74354b10fe98', '0bb3878a-fb89-455d-a84c-bdb9a26b1643', '2bcfb449-5bbb-430a-b5cc-82d6d3b35f93', '1.1',
   $$Define confidentiality, integrity and availability, and the supporting properties.$$,
   'high'::criticality, 'weekly'::task_frequency, '1_remember'::bloom_level,
   true, false,
   $$the three core properties and the four supporting properties, and their standard definitions.$$,
   $$states each property and its definition accurately; identifies which property a stated definition describes.$$,
   $$holds the core vocabulary reliably enough to use it without re-deriving it.$$, 1),
  ('127dcc5f-afea-4605-b19f-aba73876c688', '0bb3878a-fb89-455d-a84c-bdb9a26b1643', '2bcfb449-5bbb-430a-b5cc-82d6d3b35f93', '1.2',
   $$Distinguish asset, threat, vulnerability, risk and control and explain how they relate.$$,
   'high'::criticality, 'weekly'::task_frequency, '2_understand'::bloom_level,
   true, false,
   $$what each of the five terms means and how they compose into a risk.$$,
   $$distinguishes the five terms in a described situation; explains why a vulnerability without a threat is not a risk.$$,
   $$reasons about security situations in the standard's vocabulary rather than in colloquial terms.$$, 2),
  ('4be4fbb3-1c5f-4727-bb80-0c8cc25ce37a', '0bb3878a-fb89-455d-a84c-bdb9a26b1643', '2bcfb449-5bbb-430a-b5cc-82d6d3b35f93', '1.3',
   $$Explain the difference between an information security event, incident and breach.$$,
   'medium'::criticality, 'occasional'::task_frequency, '2_understand'::bloom_level,
   true, false,
   $$the definitions of event, incident and breach and the thresholds between them.$$,
   $$explains why not every event is an incident and not every incident is a breach.$$,
   $$recognizes that escalation language carries consequences and is not interchangeable.$$, 3),
  ('88e4fd5c-c15a-4a5c-be32-e33505f9bdab', '0bb3878a-fb89-455d-a84c-bdb9a26b1643', '2bcfb449-5bbb-430a-b5cc-82d6d3b35f93', '1.4',
   $$Recognize the core members of the ISO/IEC 27000 family and what each does.$$,
   'medium'::criticality, 'per_exam'::task_frequency, '1_remember'::bloom_level,
   true, false,
   $$which standard in the family carries requirements, which carries control guidance, which carries risk guidance, and the role of the overview document.$$,
   $$names the function of each core family member.$$,
   $$knows where to look rather than assuming one standard contains everything.$$, 4),
  ('cc856f79-68a5-41fc-b87d-2597218a7b0b', '0bb3878a-fb89-455d-a84c-bdb9a26b1643', '2bcfb449-5bbb-430a-b5cc-82d6d3b35f93', '1.5',
   $$Explain how AI systems change the information security attack surface.$$,
   'high'::criticality, 'weekly'::task_frequency, '2_understand'::bloom_level,
   true, false,
   $$the exposure AI systems introduce beyond conventional application surface - the model as an asset, prompts as data, the inference boundary.$$,
   $$explains why an AI system extends attack surface rather than merely adding a feature.$$,
   $$treats AI adoption as a change to the security picture rather than a procurement event.$$, 5),
  ('fec09deb-6c85-42ad-93d1-b2eccf14af41', '0bb3878a-fb89-455d-a84c-bdb9a26b1643', '2bcfb449-5bbb-430a-b5cc-82d6d3b35f93', '1.6',
   $$Distinguish model-level risks from agentic risks.$$,
   'high'::criticality, 'weekly'::task_frequency, '2_understand'::bloom_level,
   true, false,
   $$the distinction between a model treated as input-in output-out and a system that plans, holds memory, calls tools and acts.$$,
   $$distinguishes a model-level risk from an agentic one in a described deployment; explains why autonomy widens blast radius.$$,
   $$does not apply chatbot-era assumptions to an agent.$$, 6),
  ('d31d0feb-25c0-4ac3-9a3e-e26e9e7720b2', '0bb3878a-fb89-455d-a84c-bdb9a26b1643', '2bcfb449-5bbb-430a-b5cc-82d6d3b35f93', '1.7',
