   $$uses shared vocabulary so a concern can be communicated and tracked rather than described ad hoc.$$, 7),
  ('9c113a46-1f0e-4af9-8a3e-17152197d15e', '0bb3878a-fb89-455d-a84c-bdb9a26b1643', 'd29dfadc-9722-44b1-b687-47a2f30389f3', '2.1',
