  ('9fbaeb3c-4226-43b0-aaf3-4c99a5eeb095', '0bb3878a-fb89-455d-a84c-bdb9a26b1643', 'd29dfadc-9722-44b1-b687-47a2f30389f3', '2.2',
   $$Explain clause 4 - internal and external issues, and interested parties.$$,
