   $$applies an established process to an unfamiliar incident class.$$, 47),
  ('aee54804-5702-4953-a790-304d70830495', '0bb3878a-fb89-455d-a84c-bdb9a26b1643', '47c51bc6-4af0-4f72-9ecd-52e133c0413d', '5.8',
